def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        result.append(f"{ch}{count}")
        i = j
    return "".join(result)

def aplanar(datos):
    def flatten_element(elem):
        if isinstance(elem, (list, tuple)):
            flat = []
            for sub in elem:
                if isinstance(sub, (list, tuple)):
                    flat.extend(flatten_element(sub))
                else:
                    flat.append(sub)
            return flat
        else:
            return [elem]

    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            result.extend(flatten_element(item))
        else:
            result.append(item)
    return result

