from io import StringIO

def parsear_ventas(texto: str) -> list[dict]:
    """
    Parse CSV text of sales data.

    Parameters:
    - texto: string containing CSV content. The first line must be exactly
              'fecha,producto,cantidad,precio'. Fields may be quoted if they contain commas.

    Returns:
        A list of dictionaries with keys 'fecha', 'producto', 'cantidad', 'precio'.
    """
    if not texto or not texto.strip():
        return []

    reader = csv.reader(StringIO(texto))
    rows_data = []
    header_found = False

    for row in reader:
        # Skip empty lines (or lines that contain only whitespace)
        if not row or all(cell.strip() == '' for cell in row):
            continue

        if not header_found:
            expected_header = ["fecha", "producto", "cantidad", "precio"]
            if row != expected_header:
                raise ValueError(f"Header mismatch. Expected {expected_header}, got {row}")
            header_found = True
        else:
            # Expect exactly four fields in each data row
            if len(row) != 4:
                raise ValueError(f"Row has {len(row)} fields, expected 4: {row}")
            fecha, producto, cantidad_str, precio_str = row

            # Convert quantity to integer and check non-negative
            try:
                cantidad = int(cantidad_str)
            except ValueError:
                raise ValueError(f"Quantity '{cantidad_str}' is not an integer")
            if cantidad < 0:
                raise ValueError(f"Quantity {cantidad} must be non-negative")

            # Convert price to float
            try:
                precio = float(precio_str)
            except ValueError:
                raise ValueError(f"Price '{precio_str}' is not a number")

            rows_data.append({
                "fecha": fecha,
                "producto": producto,
                "cantidad": cantidad,
                "precio": precio
            })

    return rows_data

